// 1. Young Generation (단명 객체)
function createTemp() {
  const temp = { id: Math.random() };
  // 함수 종료 시 참조가 끊기며 GC 대상이 됨
}

// 2. Old Generation (장수 객체)
const cache = [];
function save(data) {
  cache.push(data); // 전역 배열이 참조를 유지함
}

createTemp(); // Young 영역에 할당되었다가 금방 수거됨
createTemp();

save({ type: 'important' }); // GC를 여러 번 버티면 Old 영역으로 승격됨
